-- churchApp: score images and printed music facts for the Nau Mpro reader.
-- Adds score_images (scan file names in the public 'hymn-scores' bucket, in reading order)
-- and music (key, time signature, printed chords) to lyric_songs, then fills them for the 520 hymns.
-- Run once in the Supabase SQL editor, after hymn-scores.sql. Safe to run twice.

alter table public.lyric_songs add column if not exists score_images text[] not null default '{}';
alter table public.lyric_songs add column if not exists music jsonb not null default '{}'::jsonb;

